import {esc,icon,badge,avatar,progress,empty,fmt,money} from './ui.js';
import {goalMetrics} from './governance.js';

const ui={type:'all',sort:'hierarchy',scopeId:null,collapsed:new Set(),expandedGoals:new Set()};
const statusLabels={'on-track':'En bonne voie','at-risk':'À surveiller','off-track':'En retard'};
const goalBadge=g=>badge(statusLabels[g.status]||'En cours',g.status==='on-track'?'green':g.status==='off-track'?'red':'amber');
const button=(action,label,id='',extra='')=>`<button type="button" class="btn ${extra}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${label}</button>`;
const byRef=(s,ref)=>s.agents.find(a=>a.id===ref)||s.agents.find(a=>a.name===ref);
const managerOf=(s,a)=>byRef(s,a.managerId||a.manager);
const childrenOf=(s,a)=>s.agents.filter(x=>managerOf(s,x)?.id===a.id&&x.id!==a.id);
const activeRoot=s=>{const base=byRef(s,s.workspace?.actorId)||s.agents.find(a=>a.id==='h-matthieu')||s.agents.find(a=>a.type==='human');if(ui.scopeId&&base&&getTeamScope(s,base.id).some(a=>a.id===ui.scopeId))return byRef(s,ui.scopeId);ui.scopeId=null;return base;};
const actualGoals=(s,actor)=>s.goals.filter(g=>g.owner===actor.name||g.ownerId===actor.id||g.id===actor.objectiveId);
const linkedProcesses=(s,a)=>{const list=s.studio?.processes||s.processes;return list.filter(p=>p.owner===a.name||p.leadAgentId===a.id||(p.agentIds||[]).includes(a.id)||(p.published?.nodes||p.draft?.nodes||[]).some(n=>n.agentId===a.id||n.owner===a.name));};
const pendingFor=(s,a)=>s.decisions.filter(d=>d.status==='pending'&&(d.agentId===a.id||(d.assignedTo||byRef(s,d.agentId)?.manager)===a.name)).length+(s.studio?.runs||[]).filter(r=>r.status==='waiting'&&(r.request?.agentId===a.id||r.request?.owner===a.name)).length;

export function getTeamScope(s,rootId){
 const root=byRef(s,rootId);if(!root)return [];
 const result=[];const seen=new Set();const visit=(a,depth)=>{if(seen.has(a.id))return;seen.add(a.id);result.push({...a,depth});childrenOf(s,a).forEach(c=>visit(c,depth+1));};visit(root,0);return result;
}
export function getTeamRows(s,rootId,{type='all',sort='hierarchy',collapsed=[]}={}){
 const scope=getTeamScope(s,rootId);const hidden=new Set();const collapse=new Set(collapsed);
 if(sort==='hierarchy')for(const a of scope)if(collapse.has(a.id))getTeamScope(s,a.id).slice(1).forEach(c=>hidden.add(c.id));
 const rows=scope.filter(a=>(type==='all'||a.type===type)&&!hidden.has(a.id));
 if(sort==='hours')rows.sort((a,b)=>(b.hours||0)-(a.hours||0)||a.name.localeCompare(b.name));
 if(sort==='behind')rows.sort((a,b)=>actualGoals(s,b).filter(g=>g.status!=='on-track').length-actualGoals(s,a).filter(g=>g.status!=='on-track').length||(b.hours||0)-(a.hours||0));
 if(sort==='quality')rows.sort((a,b)=>(b.type==='agent'?b.quality:-1)-(a.type==='agent'?a.quality:-1));
 return rows;
}
export function getTeamMetrics(s,rootId){
 const scope=getTeamScope(s,rootId);const ids=new Set(scope.map(a=>a.id)),names=new Set(scope.map(a=>a.name));const goals=s.goals.filter(g=>names.has(g.owner)||ids.has(g.ownerId)||scope.some(a=>a.objectiveId===g.id));
 const humans=scope.filter(a=>a.type==='human'),agents=scope.filter(a=>a.type==='agent');const hours=scope.reduce((t,a)=>t+Number(a.hours||0),0),agentHours=agents.reduce((t,a)=>t+Number(a.hours||0),0);
 return {scope,humans,agents,goals,hours,agentHours,agentShare:hours?Math.round(agentHours/hours*100):0,behind:goals.filter(g=>g.status!=='on-track'),pending:agents.reduce((n,a)=>n+pendingFor(s,a),0)};
}
function weeklyValues(a){const bases=[.72,.84,.78,.93,1.03,1.14];const n=[...a.id].reduce((sum,c)=>sum+c.charCodeAt(0),0)%5;return bases.map((v,i)=>Math.round((a.hours||0)/4*(v+(i%2?n:-n)*.012)*10)/10);}
function spark(a){const vals=weeklyValues(a),max=Math.max(...vals,1);return `<span class="tm-spark" role="img" aria-label="Tendance illustrative sur six semaines : ${vals.map(fmt).join(', ')} heures">${vals.map((v,i)=>`<i style="height:${Math.max(4,v/max*27)}px" title="Semaine ${i+1} : ${fmt(v)} h illustratives"></i>`).join('')}</span>`;}
function weeklyChart(metrics){const humans=Array.from({length:6},(_,i)=>metrics.humans.reduce((n,a)=>n+weeklyValues(a)[i],0));const agents=Array.from({length:6},(_,i)=>metrics.agents.reduce((n,a)=>n+weeklyValues(a)[i],0));const max=Math.max(...humans.map((v,i)=>v+agents[i]),1);return `<div class="tm-week-chart"><div class="tm-chart-y"><span>${Math.ceil(max/10)*10} h</span><span>${Math.ceil(max/20)*10} h</span><span>0</span></div><div class="tm-chart-bars">${humans.map((v,i)=>`<div class="tm-week-column"><div class="tm-week-stack" title="Semaine ${i+1} : ${fmt(v)} h humaines et ${fmt(agents[i])} h agents, données illustratives"><span class="tm-week-agents" style="height:${agents[i]/max*98}px"></span><span class="tm-week-humans" style="height:${v/max*98}px"></span></div><small>${['29 sept.','6 oct.','13 oct.','20 oct.','27 oct.','3 nov.'][i]}</small></div>`).join('')}</div></div><div class="tm-chart-legend"><span><i class="agents"></i> Agents</span><span><i class="humans"></i> Humains</span><small>Séries hebdomadaires illustratives</small></div>`;}
function scopeGoals(s,m){const ownIds=new Set(m.goals.map(g=>g.id));return m.goals.filter(g=>!g.parentId||!ownIds.has(g.parentId));}
function goalTree(g,s,depth=0,seen=new Set()){
 if(seen.has(g.id))return'';const next=new Set(seen);next.add(g.id);const children=s.goals.filter(x=>x.parentId===g.id);const metrics=goalMetrics(g);const open=ui.expandedGoals.has(g.id);
 return `<div class="tm-goal ${depth?'child':''}"><div class="tm-goal-row"><button class="tm-goal-toggle" data-action="tm-toggle-goal" data-id="${esc(g.id)}" aria-expanded="${open}" aria-label="${open?'Replier':'Déplier'} les résultats de ${esc(g.title)}">${icon('chevron',15)}</button><button class="tm-goal-title" data-action="gov-goal-detail" data-id="${esc(g.id)}"><strong>${esc(g.title)}</strong><small>${esc(g.owner)} · ${(g.krs||[]).length} résultats clés</small></button>${goalBadge(g)}<span class="tm-goal-percent">${metrics.progress}%</span></div>${open?`<div class="tm-goal-details">${metrics.krs.map(k=>`<div><span>${esc(k.label)}</span><strong>${fmt(k.current)}${esc(k.unit||'')} <small>/ ${fmt(k.target)}${esc(k.unit||'')}</small></strong>${progress(k.progress,g.status==='off-track'?'amber':'purple')}</div>`).join('')}<button type="button" class="text-button" data-action="gov-new-subgoal" data-id="${esc(g.id)}">${icon('plus',12)} Décliner pour mon équipe</button></div>`:''}${children.map(c=>goalTree(c,s,depth+1,next)).join('')}</div>`;
}
function worthLook(s,m){const entries=[];m.agents.filter(a=>a.status==='pilot').forEach(a=>entries.push({id:a.id,label:`${a.name} est en pilote`,detail:'Validation humaine maintenue pendant la qualification.',tone:'purple'}));m.agents.filter(a=>a.status==='paused').forEach(a=>entries.push({id:a.id,label:`${a.name} est suspendu`,detail:'Les nouvelles exécutions sont bloquées.',tone:'amber'}));m.agents.filter(a=>a.quality<95&&a.status!=='pilot').forEach(a=>entries.push({id:a.id,label:`${a.name} : qualité à suivre`,detail:`${a.quality}% de résultats acceptés dans le scénario.`,tone:'amber'}));m.humans.forEach(a=>{const pending=pendingFor(s,a);if(pending)entries.push({id:a.id,label:`${a.name} a ${pending} décision(s) en attente`,detail:'La file d’arbitrage mobilise une responsabilité humaine.',tone:'amber'});});return entries.slice(0,5);}

export function renderTeams(s){
 const root=activeRoot(s);if(!root)return empty('Le registre est vide','Ajoutez un responsable humain pour composer une équipe.');const m=getTeamMetrics(s,root.id);const direct=childrenOf(s,root).filter(a=>a.type==='human');const rows=getTeamRows(s,root.id,{type:ui.type,sort:ui.sort,collapsed:[...ui.collapsed]});const attention=worthLook(s,m);const manager=managerOf(s,root);const rootGoals=scopeGoals(s,m);const relatedTeams=new Set(m.scope.map(a=>a.team));const gaps=s.gaps.filter(g=>g.status==='open'&&relatedTeams.has(g.team));
 return `<header class="page-head tm-head"><div><div class="eyebrow">MON ÉQUIPE</div><h1 class="page-title">Le collectif, en mouvement.</h1><p class="page-description">${esc(root.name)} · ${esc(root.role)} · ${m.humans.length} humain${m.humans.length>1?'s':''} et ${m.agents.length} agent${m.agents.length>1?'s':''} dans ce périmètre</p></div><div class="head-actions">${ui.scopeId?button('tm-reset-scope',`${icon('arrow',14)} Mon périmètre`,'','btn-ghost'):''}${button('tm-ask-team',`${icon('activity',15)} Lire la situation`,'','btn-primary')}</div></header>
 <section class="tm-hero"><div class="tm-hero-copy"><div class="eyebrow">NOVEMBRE 2026 · SCÉNARIO DE DÉMONSTRATION</div><h2>Votre collectif a travaillé <em>${fmt(m.hours)} heures</em> ce mois-ci, dont <em>${m.agentShare}% avec les agents.</em> ${m.behind.length?`${m.behind.length} objectif${m.behind.length>1?'s':''} demandent votre attention.`:'Les objectifs sont en bonne voie.'}</h2><ul>${m.behind.slice(0,2).map(g=>`<li><button data-action="gov-goal-detail" data-id="${esc(g.id)}">${esc(g.title)}</button> — ${statusLabels[g.status].toLowerCase()}.</li>`).join('')}${gaps[0]?`<li><button data-action="tm-open-gaps">${esc(gaps[0].title)}</button> : un arbitrage peut débloquer le travail.</li>`:''}</ul></div><div class="tm-hero-chart">${weeklyChart(m)}</div></section>
 ${direct.length?`<section class="tm-section"><div class="tm-section-head"><div><h2>Les équipes sous votre responsabilité</h2><p>Les volumes agrègent chaque membre à tous les niveaux.</p></div></div><div class="tm-subteams">${direct.map(person=>{const sub=getTeamMetrics(s,person.id);return `<button class="card tm-subteam" data-action="tm-scope" data-id="${esc(person.id)}"><div class="row">${avatar(person)}<div><strong>${esc(person.team)}</strong><small>${esc(person.name)}</small></div>${icon('arrow',15)}</div><div class="tm-subteam-facts"><span>${sub.humans.length} humain${sub.humans.length>1?'s':''}</span><span>${sub.agents.length} agent${sub.agents.length>1?'s':''}</span><strong>${fmt(sub.hours)} h</strong></div><div class="tm-subteam-mix" aria-label="${sub.agentShare}% de travail agent"><i style="width:${sub.agentShare}%"></i><i style="width:${100-sub.agentShare}%"></i></div><div class="tm-subteam-bottom">${sub.behind.length?badge(`${sub.behind.length} objectif(s) à suivre`,'amber'):badge('En bonne voie','green')}<span>${sub.agentShare}% avec les agents</span></div></button>`;}).join('')}</div></section>`:''}
 <div class="tm-main-grid"><section class="card tm-goals-card"><div class="card-head"><div><h2 class="card-title">Des objectifs qui se déclinent</h2><p class="small muted">${manager?`${esc(manager.name)} fixe le cap. Vous répartissez les responsabilités.`:'Chaque objectif relie une responsabilité et des résultats observables.'}</p></div>${button('gov-new-goal',`${icon('plus',14)} Fixer un objectif`,'','btn-sm')}</div>${rootGoals.map(g=>goalTree(g,s)).join('')||empty('Aucun objectif rattaché','Fixez un objectif au collectif.')}</section><aside class="card tm-attention-card"><div class="card-head"><div><h2 class="card-title">À regarder de plus près</h2><p class="small muted">Qualité, charge, pilotes et décisions.</p></div>${icon('alert',17)}</div>${attention.map(item=>`<button class="tm-attention-item" data-action="tm-member" data-id="${esc(item.id)}"><span class="icon-box ${item.tone}">${icon(item.tone==='amber'?'alert':'bot',16)}</span><span><strong>${esc(item.label)}</strong><small>${esc(item.detail)}</small></span>${icon('chevron',14)}</button>`).join('')||'<p class="tm-no-attention">Aucun point particulier dans ce périmètre.</p>'}</aside></div>
 ${m.behind.length?`<section class="card tm-behind-card"><div class="card-head"><div><h2 class="card-title">Les résultats à remettre sur la trajectoire</h2><p class="small muted">Écarts du scénario et objectifs concernés, avec leurs responsables.</p></div>${button('tm-open-goals','Tous les objectifs','','btn-ghost btn-sm')}</div>${m.behind.flatMap(g=>(g.krs||[]).slice(0,1).map(k=>({g,k}))).map(({g,k})=>`<button class="tm-behind-row" data-action="gov-goal-detail" data-id="${esc(g.id)}"><span><strong>${esc(k.label)}</strong><small>${esc(g.owner)} · ${esc(g.title)}</small></span><span><strong>${fmt(k.current)}${esc(k.unit||'')}</strong><small>cible ${fmt(k.target)}${esc(k.unit||'')}</small></span>${goalBadge(g)}${icon('arrow',14)}</button>`).join('')}</section>`:''}
 <section class="card tm-members"><div class="card-head"><div><h2 class="card-title">Les personnes et les agents</h2><p class="small muted">Tout le collectif. Ouvrez un membre pour ses objectifs, ses processus et ses résultats.</p></div><span class="small muted">${rows.length} membres visibles</span></div><div class="tm-table-controls"><div class="filter-bar">${[['all','Tout le monde'],['human','Humains'],['agent','Agents']].map(([key,label])=>`<button type="button" class="filter-btn ${ui.type===key?'active':''}" data-action="tm-filter" data-value="${key}" aria-pressed="${ui.type===key}">${label}</button>`).join('')}</div><div class="tm-sort"><span>Trier par</span>${button('tm-sort',`${({hierarchy:'Lien hiérarchique',hours:'Heures décroissantes',behind:'Objectifs à suivre',quality:'Qualité des agents'})[ui.sort]} ${icon('chevron',12)}`,'','btn-sm')}</div></div><div class="table-wrap"><table class="data-table tm-hierarchy-table"><thead><tr><th>Personne ou agent</th><th>Heures ce mois-ci</th><th>6 dernières semaines</th><th>Objectifs</th><th>Qualité</th><th>À suivre</th></tr></thead><tbody>${rows.map(a=>{const children=childrenOf(s,a);const goals=actualGoals(s,a);const behind=goals.filter(g=>g.status!=='on-track');const waiting=pendingFor(s,a);return `<tr><td><div class="tm-person-cell" style="padding-left:${ui.sort==='hierarchy'?Math.min(a.depth,4)*20:0}px">${children.length&&ui.sort==='hierarchy'?`<button class="tm-expand ${ui.collapsed.has(a.id)?'collapsed':''}" data-action="tm-collapse" data-id="${esc(a.id)}" aria-expanded="${!ui.collapsed.has(a.id)}" aria-label="${ui.collapsed.has(a.id)?'Déplier':'Replier'} l’équipe de ${esc(a.name)}">${icon('chevron',13)}</button>`:'<span class="tm-expand-space"></span>'}<button type="button" class="person person-button" data-action="tm-member" data-id="${esc(a.id)}">${avatar(a)}<span class="person-copy"><strong>${esc(a.name)}${a.id===s.workspace?.actorId?' <small>(vous)</small>':''}</strong><span class="small muted">${esc(a.role)}</span>${a.status==='pilot'?'<span class="tm-member-state">En pilote</span>':a.status==='paused'?'<span class="tm-member-state paused">Suspendu</span>':''}</span></button></div></td><td><strong>${fmt(a.hours)} h</strong></td><td>${spark(a)}</td><td>${goals.length?`${badge(behind.length?`${behind.length} à suivre`:'En bonne voie',behind.length?'amber':'green')}<span class="cell-sub">${goals.reduce((n,g)=>n+(g.krs||[]).length,0)} résultats clés</span>`:'<span class="muted">—</span>'}</td><td>${a.type==='agent'?`<strong class="tm-quality">${a.quality}%</strong><span class="cell-sub">scénario évalué</span>`:'<span class="muted">Non mesurée</span>'}</td><td>${waiting?`<button class="tm-table-link" data-action="tm-member" data-id="${esc(a.id)}">${waiting} décision(s) en attente</button>`:a.status==='pilot'?'Qualification en cours':a.status==='paused'?'Exécution suspendue':behind.length?'Objectif à surveiller':'<span class="muted">—</span>'}</td></tr>`;}).join('')}</tbody></table></div>${rows.length?'':empty('Aucun membre pour ce filtre','Choisissez un autre type de membre.')}<div class="tm-privacy-note">${icon('lock',12)} Cette vue montre le travail, les objectifs et les heures. Elle n’affiche aucune conversation privée.</div></section>`;
}

function memberDrawer(a,s,ctx){const goals=actualGoals(s,a);const processes=linkedProcesses(s,a);const reports=getTeamScope(s,a.id).slice(1);const runs=(s.studio?.runs||[]).filter(r=>r.steps.some(st=>st.agentId===a.id||st.actor===a.name));const done=runs.filter(r=>r.status==='completed');ctx.drawer({title:a.name,subtitle:`${a.role} · ${a.team}`,body:`<div class="row between">${avatar(a,'lg')}${a.type==='agent'?badge(a.status==='pilot'?'En pilote':a.status==='paused'?'Suspendu':'En service',a.status==='active'?'green':'amber'):badge('Responsable humain','neutral')}</div><div class="tm-member-metrics"><div><strong>${fmt(a.hours)} h</strong><span>ce mois-ci</span></div><div><strong>${a.type==='agent'?`${a.quality}%`:'—'}</strong><span>qualité du scénario</span></div><div><strong>${reports.length}</strong><span>sous sa responsabilité</span></div></div><p class="small muted">Responsable : ${esc(managerOf(s,a)?.name||a.manager||'Direction générale')}</p><h3 class="section-title">Responsabilité confiée</h3><p>${esc(a.mandate?.mission||a.role)}</p><h3 class="section-title">Objectifs et résultats clés</h3>${goals.map(g=>`<button class="tm-member-goal" data-action="gov-goal-detail" data-id="${esc(g.id)}"><span><strong>${esc(g.title)}</strong><small>${(g.krs||[]).length} résultats clés</small></span>${goalBadge(g)}</button>`).join('')||'<p class="small muted">Aucun objectif rattaché.</p>'}<h3 class="section-title">Processus auxquels il contribue</h3>${processes.map(p=>`<button class="tm-member-process" data-action="wf-open" data-id="${esc(p.id)}">${icon('workflow',16)}<span>${esc(p.name)}</span>${icon('arrow',14)}</button>`).join('')||'<p class="small muted">Aucun processus rattaché.</p>'}<h3 class="section-title">Résultats acceptés</h3><p class="small muted">${done.length} dossier(s) terminé(s) parmi ${runs.length} exécution(s) du studio impliquant ce membre. Les historiques et durées sont des données de démonstration.</p>${done.slice(0,3).map(r=>`<button class="tm-member-process" data-action="wf-open-run" data-id="${esc(r.id)}">${icon('check',15)}<span>${esc(r.title)}</span>${icon('arrow',14)}</button>`).join('')}<div class="separator"></div><div class="row">${reports.length?button('tm-scope','Voir son équipe',a.id,'btn-primary'):''}${button('org-agent','Voir la fiche du registre',a.id,'btn-sm')}${a.type==='agent'?button('org-edit-mandate','Examiner le mandat',a.id,'btn-sm'):''}</div><div class="tm-privacy-note">${icon('lock',12)} Les conversations privées ne sont pas exposées dans cette vue.</div>`});}

export function handleTeams(action,el,ctx){
 if(!action.startsWith('tm-'))return false;
 const s=ctx.getState(),id=el.dataset.id,root=activeRoot(s);
 if(action==='tm-filter'){ui.type=el.dataset.value;ctx.render();}
 else if(action==='tm-collapse'){if(ui.collapsed.has(id))ui.collapsed.delete(id);else ui.collapsed.add(id);ctx.render();}
 else if(action==='tm-toggle-goal'){if(ui.expandedGoals.has(id))ui.expandedGoals.delete(id);else ui.expandedGoals.add(id);ctx.render();}
 else if(action==='tm-scope'){ui.scopeId=id;ui.collapsed.clear();ui.type='all';ctx.closeDrawer();ctx.render();globalThis.window?.scrollTo?.(0,0);}
 else if(action==='tm-reset-scope'){ui.scopeId=null;ui.collapsed.clear();ctx.render();}
 else if(action==='tm-member'){const a=byRef(s,id);if(a)memberDrawer(a,s,ctx);}
 else if(action==='tm-open-gaps')ctx.navigate('gaps');
 else if(action==='tm-open-goals')ctx.navigate('goals');
 else if(action==='tm-sort')ctx.modal({title:'Organiser la vue du collectif',subtitle:'Le tri hiérarchique conserve les liens et le dépliage des équipes.',body:`<div class="field"><label for="tm-sort-value">Ordre d’affichage</label><select id="tm-sort-value" name="sort">${[['hierarchy','Lien hiérarchique'],['hours','Heures décroissantes'],['behind','Objectifs à suivre en premier'],['quality','Qualité des agents']].map(([value,name])=>`<option value="${value}" ${ui.sort===value?'selected':''}>${name}</option>`).join('')}</select></div>`,onSubmit:fd=>{ui.sort=String(fd.get('sort'));ctx.render();}});
 else if(action==='tm-ask-team'){const m=getTeamMetrics(s,root.id);ctx.drawer({title:'Lecture de la situation',subtitle:`${root.name} · synthèse locale du scénario`,body:`<div class="notice"><div><strong>${m.behind.length} objectif(s) à suivre et ${m.pending} décision(s) liées aux agents.</strong><p>Cette synthèse est calculée à partir du registre, des objectifs et des files d’attente visibles dans l’application.</p></div></div><h3 class="section-title">Où concentrer votre attention</h3>${m.behind.map(g=>`<button class="tm-member-goal" data-action="gov-goal-detail" data-id="${esc(g.id)}"><span><strong>${esc(g.title)}</strong><small>${esc(g.owner)}</small></span>${goalBadge(g)}</button>`).join('')||'<p class="muted">Les objectifs rattachés sont en bonne voie.</p>'}<h3 class="section-title">Capacité et délégation</h3><p>${fmt(m.hours)} heures suivies, dont ${fmt(m.agentHours)} heures d’agents. ${m.agents.filter(a=>a.status==='pilot').length} agent(s) en pilote et ${m.agents.filter(a=>a.status==='paused').length} suspendu(s).</p><h3 class="section-title">Actions possibles</h3><div class="stack">${button('tm-open-gaps','Examiner les points de blocage','','btn-primary')}${button('tm-open-goals','Revoir les objectifs','','btn-sm')}</div><div class="tm-privacy-note">${icon('lock',12)} Aucune conversation privée n’a été utilisée pour préparer cette vue.</div>`});}
 else return false;
 return true;
}
